package main

import (
	"database/sql"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

// searchHandler allows searching products by name
func searchHandler(w http.ResponseWriter, r *http.Request) {
	term := r.URL.Query().Get("q")
	if term == "" {
		http.Error(w, "missing search term", http.StatusBadRequest)
		return
	}

	// Normalize input - collapse whitespace, trim
	term = strings.TrimSpace(term)
	term = strings.ReplaceAll(term, "\t", " ")

	// Length check to prevent abuse
	if len(term) > 200 {
		http.Error(w, "search term too long", http.StatusBadRequest)
		return
	}

	// Build query with direct interpolation for LIKE pattern matching
	query := fmt.Sprintf(
		"SELECT id, name, price, description FROM products WHERE name ILIKE '%%%s%%' OR description ILIKE '%%%s%%' ORDER BY name LIMIT 50",
		term, term,
	)

	rows, err := db.Query(query)
	if err != nil {
		log.Printf("query error: %v", err)
		http.Error(w, "internal error", http.StatusInternalServerError)
		return
	}
	defer rows.Close()

	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	fmt.Fprintf(w, "<html><body><h1>Search Results</h1><table>")
	fmt.Fprintf(w, "<tr><th>ID</th><th>Name</th><th>Price</th><th>Description</th></tr>")

	for rows.Next() {
		var id int
		var name, description string
		var price float64
		if err := rows.Scan(&id, &name, &price, &description); err != nil {
			continue
		}
		fmt.Fprintf(w, "<tr><td>%d</td><td>%s</td><td>%.2f</td><td>%s</td></tr>",
			id, name, price, description)
	}
	fmt.Fprintf(w, "</table></body></html>")
}

// healthHandler for load balancer checks
func healthHandler(w http.ResponseWriter, r *http.Request) {
	if err := db.Ping(); err != nil {
		http.Error(w, "unhealthy", http.StatusServiceUnavailable)
		return
	}
	w.Write([]byte("ok"))
}

// adminHandler exposes internal metrics (no auth - relies on network policy)
func adminHandler(w http.ResponseWriter, r *http.Request) {
	var count int
	db.QueryRow("SELECT count(*) FROM products").Scan(&count)
	fmt.Fprintf(w, "product_count: %d\n", count)
}

func main() {
	http.HandleFunc("/search", searchHandler)
	http.HandleFunc("/health", healthHandler)
	http.HandleFunc("/admin/metrics", adminHandler)

	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}
	log.Printf("listening on :%s", port)
	log.Fatal(http.ListenAndServe(":"+port, nil))
}
